34	 */
35	int CIDRFromMask(uint32_t netmask)
36	{
37	    netmask = ntohl(netmask);
38	    if (netmask == 0) {
39	        return 0;
40	    }
41	    int p = 0;
42	    bool seen_1 = false;
43	    while (netmask > 0) {
44	        if (netmask & 1) {
45	            seen_1 = true;
46	            p++;
47	        } else {
48	            if (seen_1) {
49	                return -1;
50	            }
51	        }
52	        netmask >>= 1;
53	    }
54	    return p;
55	}
