57	uint32_t CIDRGet(int cidr)
58	{
59	    if (cidr <= 0 || cidr > 32)
60	        return 0;
61	    uint32_t netmask = htonl(0xFFFFFFFF << (32UL - (uint32_t)cidr));
62	    SCLogDebug("CIDR %d -> netmask %08X", cidr, netmask);
