335	static RADIX_NODE_TYPE *AddKey(RADIX_TREE_TYPE *tree, const RADIX_CONFIG_TYPE *config,
336	        const uint8_t *key_stream, uint8_t netmask, void *user, const bool exclusive)
337	{
338	    DEBUG_VALIDATE_BUG_ON(config == NULL);
