#define SCMalloc(a)     malloc((a))
#define SCCalloc(a, b)  calloc((a), (b))
#define SCFree(a)       free((a))
#define SCStrdup(a)     strdup((a))
#define SCMemcmp(a, b, c) memcmp((a), (b), (c))
#define BIT_U64(n)      ((uint64_t)1 << (n))
#define MIN(a, b)       (((a) < (b)) ? (a) : (b))
#define unlikely(x)     (x)
#define likely(x)       (x)

#define SCLogDebug(...)
#define SCLogError(...)
#define SCLogWarning(...)
#define SCLogNotice(...)
#define FatalError(...)  do { fprintf(stderr, "fatal\n"); exit(1); } while (0)

#define BUG_ON(x)                                                                                  \
    do {                                                                                           \
        if (x) {                                                                                   \
            fprintf(stderr, "BUG_ON\n");                                                           \
            abort();                                                                               \
        }                                                                                          \
    } while (0)
#define DEBUG_VALIDATE_BUG_ON(x)
#define SCReturn        return

enum {
    SC_OK = 0,
    SC_EINVAL,
    SC_ENOMEM,
    SC_EEXIST,
    SC_ENOENT,
};
extern int sc_errno;

/* copied verbatim from src/util-ip.c so masking matches exactly */
static inline void MaskIPNetblock(uint8_t *stream, int netmask, int key_bitlen)
{
    uint32_t mask = 0;
    int i = 0;
    int bytes = key_bitlen / 8;

    for (i = 0; i < bytes; i++) {
        mask = UINT_MAX;
        if (((i + 1) * 8) > netmask) {
            if (((i + 1) * 8 - netmask) < 8)
                mask = UINT_MAX << ((i + 1) * 8 - netmask);
            else
                mask = 0;
        }
        stream[i] &= mask;
    }
}

static inline void PrintInet(int af, const void *src, char *dst, socklen_t size)
{
    if (inet_ntop(af, src, dst, size) == NULL)
        strlcpy_stub_unused: ;
}

/* util-cidr.c, verbatim */
static inline void CIDRGetIPv6(int cidr, struct in6_addr *in6)
{
    int i = 0;

    memset(in6, 0, sizeof(struct in6_addr));

    while (cidr > 8) {
        in6->s6_addr[i] = 0xff;
        cidr -= 8;
        i++;
    }

    while (cidr > 0) {
        in6->s6_addr[i] |= 0x80;
        if (--cidr > 0)
            in6->s6_addr[i] = in6->s6_addr[i] >> 1;
    }
}

static inline int CIDRFromMask(uint32_t netmask)
{
    netmask = ntohl(netmask);
    if (netmask == 0) {
        return 0;
    }
    int p = 0;
    bool seen_1 = false;
    while (netmask > 0) {
        if (netmask & 1) {
            seen_1 = true;
            p++;
        } else {
            if (seen_1) {
                return -1;
            }
        }
        netmask >>= 1;
    }
    return p;
}

static inline uint32_t CIDRGet(int cidr)
{
    if (cidr <= 0 || cidr > 32)
        return 0;
    uint32_t netmask = htonl(0xFFFFFFFF << (32UL - (uint32_t)cidr));
    return netmask;
}

static inline size_t strlcpy(char *dst, const char *src, size_t siz)
{
    size_t len = strlen(src);
    if (siz) {
        size_t n = (len >= siz) ? siz - 1 : len;
        memcpy(dst, src, n);
        dst[n] = '\0';
    }
    return len;
}

static inline int StringParseU8RangeCheck(
        uint8_t *out, int base, size_t len, const char *str, int min, int max)
{
    char *end = NULL;
    if (str == NULL || *str == '\0')
        return -1;
    long v = strtol(str, &end, base);
    if (end == str || (end && *end != '\0'))
        return -1;
    if (v < min || v > max)
        return -1;
    *out = (uint8_t)v;
    return (int)(end - str);
}

#endif

