static int AddHostOSInfo(const char *host_os, const char *host_os_ip_range, int is_ipv4)
{
    char *ip_str = NULL;
    char *ip_str_rem = NULL;
    int *user_data = NULL;
    bool recursive = false;

    if (host_os == NULL || host_os_ip_range == NULL || strlen(host_os_ip_range) == 0)
        return -1;

    int v = MapName(host_os);
    if (v == -1)
        return -1;
