        ip_str_rem[0] = '\0';
        ip_str_rem++;
        recursive = true;
    }

    if (strchr(ip_str, ':') == NULL) {
        if (!SCRadix4AddKeyIPV4String(&tree4, &cfg4, ip_str, user_data)) {
