#!/usr/bin/env python3
"""Standalone host-OS-policy / CIDR helper.

Faithful port of the Suricata pieces used for TCP stream reassembly OS policy
lookups, so a config hand-off can answer "which OS policy applies to this
address" without running the engine:

  * src/util-cidr.c               -> CIDRFromMask / CIDRGet / CIDRGetIPv6
  * src/util-ip.c                 -> MaskIPNetblock
  * src/util-radix4-tree.c        -> SCRadix4AddKeyIPV4String
  * src/util-radix6-tree.c        -> SCRadix6AddKeyIPV6String
  * src/util-radix-tree-common.h  -> AddKey / FindKey / FindKeyIPNetblock
  * src/util-host-os-info.c       -> SCHInfoAddHostOSInfo,
                                     SCHInfoGetHostOSFlavour,
                                     SCHInfoLoadFromConfig
  * src/stream-tcp-reassemble.h   -> the OS_POLICY_* enum

Usage:
  ospolicy cidr ipv4-mask <dotted-quad>   -> CIDRFromMask, decimal (-1 if not a prefix)
  ospolicy cidr ipv4-prefix <n>           -> CIDRGet, host uint32_t as %08x
  ospolicy cidr ipv6-prefix <n>           -> CIDRGetIPv6, 16 hex bytes
  ospolicy load <yaml-path>               -> read IPs on stdin, print "<ip> <flavour>"
"""

import json
import socket
import sys

# ---------------------------------------------------------------------------
# OS policy enum -- src/stream-tcp-reassemble.h (OS_POLICY_NONE = 1, then in
# order) paired with sc_hinfo_os_policy_map from src/util-host-os-info.c.
# ---------------------------------------------------------------------------

OS_POLICY_NAMES = [
    "none",
    "bsd",
    "bsd-right",
    "old-linux",
    "linux",
    "old-solaris",
    "solaris",
    "hpux10",
    "hpux11",
    "irix",
    "macos",
    "windows",
    "vista",
    "windows2k3",
]

# OS_POLICY_NONE == 1, so value == index + 1.
OS_POLICY_NAME_TO_VALUE = {n: i + 1 for i, n in enumerate(OS_POLICY_NAMES)}
OS_POLICY_VALUE_TO_NAME = {i + 1: n for i, n in enumerate(OS_POLICY_NAMES)}


def map_enum_name_to_value(name):
    """SCMapEnumNameToValue(): strcasecmp against the map, -1 when absent."""
    if name is None:
        return -1
    return OS_POLICY_NAME_TO_VALUE.get(name.lower(), -1)


def map_enum_value_to_name(value):
    return OS_POLICY_VALUE_TO_NAME.get(value, "none")


# ---------------------------------------------------------------------------
# src/util-error.h status codes (only the ones AddKey sets).
# ---------------------------------------------------------------------------

SC_OK = 0
SC_EINVAL = 1
SC_ENOMEM = 2
SC_EEXIST = 3


class Errno(object):
    """Stand-in for the global `sc_errno`."""

    def __init__(self):
        self.value = SC_OK


sc_errno = Errno()


# ---------------------------------------------------------------------------
# src/util-cidr.c
# ---------------------------------------------------------------------------


def cidr_from_mask(netmask_net_order):
    """CIDRFromMask(): netmask is a uint32_t in network byte order.

    Returns the prefix length, or -1 when the mask is not a valid prefix.
    """
    # ntohl() of the network-order value == the big-endian interpretation.
    netmask = netmask_net_order
    if netmask == 0:
        return 0
    p = 0
    seen_1 = False
    while netmask > 0:
        if netmask & 1:
            seen_1 = True
            p += 1
        else:
            if seen_1:
                return -1
        netmask >>= 1
    return p


def cidr_get(cidr):
    """CIDRGet(): returns the netmask as a host-order uint32_t.

    The C returns htonl(0xFFFFFFFF << (32 - cidr)); callers print that raw
    uint32_t with %08x, so the result is byte-order dependent. We reproduce the
    value this host's htonl() would produce.
    """
    if cidr <= 0 or cidr > 32:
        return 0
    shifted = (0xFFFFFFFF << (32 - cidr)) & 0xFFFFFFFF
    # htonl(): swap on a little-endian host, identity on big-endian.
    if sys.byteorder == "little":
        return int.from_bytes(shifted.to_bytes(4, "big"), "little")
    return shifted


def cidr_get_ipv6(cidr):
    """CIDRGetIPv6(): returns the 16-byte in6_addr mask as a bytearray."""
    in6 = bytearray(16)
    i = 0

    while cidr > 8:
        if i >= 16:  # C would run off the end; unreachable for cidr <= 128
            break
        in6[i] = 0xFF
        cidr -= 8
        i += 1

    while cidr > 0:
        if i >= 16:
            break
        in6[i] |= 0x80
        cidr -= 1
        if cidr > 0:
            in6[i] = in6[i] >> 1

    return in6


# ---------------------------------------------------------------------------
# src/util-ip.c
# ---------------------------------------------------------------------------


def mask_ip_netblock(stream, netmask, key_bitlen):
    """MaskIPNetblock(): chop an address against a netmask, in place."""
    nbytes = key_bitlen // 8
    for i in range(nbytes):
        mask = 0xFFFFFFFF
        if ((i + 1) * 8) > netmask:
            if ((i + 1) * 8 - netmask) < 8:
                mask = (0xFFFFFFFF << ((i + 1) * 8 - netmask)) & 0xFFFFFFFF
            else:
                mask = 0
        # stream[] is uint8_t, so the store truncates to the low byte.
        stream[i] &= mask & 0xFF


def bittest(stream, bit):
    """RADIX_BITTEST(stream[bit >> 3], 0x80 >> (bit % 8))."""
    return stream[bit >> 3] & (0x80 >> (bit % 8))


# ---------------------------------------------------------------------------
# src/util-radix-tree-common.h -- shared radix implementation. The radix4 and
# radix6 variants differ only in ADDRESS_BYTES / NETMASK_MAX and in how the
# per-node netmask bitmap is stored (uint64_t bitfield vs uint8_t[17]); both
# are pure bitmaps, so one integer bitmap covers both.
# ---------------------------------------------------------------------------


class RadixUserData(object):
    """RadixUserData: a (netmask, user) pair in a per-node list."""

    __slots__ = ("netmask", "user")

    def __init__(self, netmask, user):
        self.netmask = netmask
        self.user = user


class RadixNode(object):
    __slots__ = ("masks", "bit", "has_prefix", "prefix_stream", "user_data",
                 "left", "right", "parent")

    def __init__(self, netmask_max, address_bytes):
        self.masks = 0
        self.bit = netmask_max  # RadixCreateNode(): node->bit = NETMASK_MAX
        self.has_prefix = False
        self.prefix_stream = bytearray(address_bytes)
        self.user_data = []  # descending by netmask
        self.left = None
        self.right = None
        self.parent = None


class RadixTree(object):
    """Port of AddKey()/FindKey()/FindKeyIPNetblock()."""

    def __init__(self, netmask_max, address_bytes):
        self.head = None
        self.netmask_max = netmask_max
        self.address_bytes = address_bytes

    # -- netmask bitmap helpers (AddNetmaskToMasks & friends) ---------------

    @staticmethod
    def _netmasks_empty(node):
        return node.masks == 0

    @staticmethod
    def _netmask_isset(node, netmask):
        return (node.masks & (1 << netmask)) != 0

    @staticmethod
    def _add_netmask_to_masks(node, netmask):
        node.masks |= 1 << netmask

    def _process_internode(self, node, inter_node):
        """ProcessInternode(): split node's masks around inter_node->bit."""
        differ_bit = inter_node.bit
        rem = 0
        for x in range(0, self.netmask_max + 1):
            m = self.netmask_max - x
            if m == differ_bit:
                break
            rem |= node.masks & (1 << m)

        inter_node.masks |= node.masks
        inter_node.masks &= ~rem
        node.masks = rem

    # -- user_data list (AppendToUserDataList / AddNetmaskUserDataToNode) ---

    @staticmethod
    def _append_user_data(node, netmask, user):
        """Insert in descending netmask order, as the C list does."""
        add = RadixUserData(netmask, user)
        idx = len(node.user_data)
        for i, cur in enumerate(node.user_data):
            if add.netmask > cur.netmask:
                idx = i
                break
        node.user_data.insert(idx, add)

    @staticmethod
    def _contain_netmask(node, netmask):
        """ContainNetmask()."""
        for ud in node.user_data:
            if ud.netmask == netmask:
                return True
        return False

    @staticmethod
    def _contain_netmask_and_get_user(node, netmask, exact_match):
        """ContainNetmaskAndSetUserData().

        Returns (found, user). For exact_match only the list head is consulted,
        which is the entry with the largest netmask.
        """
        if exact_match:
            if node.user_data and node.user_data[0].netmask == netmask:
                return True, node.user_data[0].user
            return False, None

        for ud in node.user_data:
            if ud.netmask == netmask:
                return True, ud.user
        return False, None

    # -- AddKey ------------------------------------------------------------

    def add_key(self, key_stream, netmask, user, exclusive):
        """AddKey(). Returns the node, or None with sc_errno set."""
        netmask_max = self.netmask_max
        tmp_stream = bytearray(key_stream)

        # chop the ip address against a netmask
        mask_ip_netblock(tmp_stream, netmask, netmask_max)

        # the very first element in the radix tree
        if self.head is None:
            node = RadixNode(netmask_max, self.address_bytes)
            node.prefix_stream = bytearray(tmp_stream)
            node.has_prefix = True
            node.user_data = [RadixUserData(netmask, user)]
            self.head = node
            if netmask == netmask_max:
                return node
            self._add_netmask_to_masks(node, netmask)
            return node

        node = self.head

        # walk down until we reach a node that ends in a prefix
        while node.bit < netmask_max or not node.has_prefix:
            if netmask_max <= node.bit:
                if node.right is None:
                    break
                node = node.right
            else:
                if bittest(tmp_stream, node.bit):
                    if node.right is None:
                        break
                    node = node.right
                else:
                    if node.left is None:
                        break
                    node = node.left

        bottom_node = node

        # first bit position where the ips differ
        check_bit = min(node.bit, netmask_max)
        differ_bit = 0
        j = 0
        i = 0
        while (i * 8) < check_bit:
            temp = tmp_stream[i] ^ bottom_node.prefix_stream[i]
            if temp == 0:
                differ_bit = (i + 1) * 8
                i += 1
                continue

            temp = temp * 2
            if temp >= 256:
                j = 0
            elif temp >= 128:
                j = 1
            elif temp >= 64:
                j = 2
            elif temp >= 32:
                j = 3
            elif temp >= 16:
                j = 4
            elif temp >= 8:
                j = 5
            elif temp >= 4:
                j = 6
            elif temp >= 2:
                j = 7

            differ_bit = i * 8 + j
            break
        if check_bit < differ_bit:
            differ_bit = check_bit

        # walk up the tree to find where the new node fits
        parent = node.parent
        while parent is not None and differ_bit <= parent.bit:
            node = parent
            parent = node.parent

        # node with the same differing bit position already present
        if differ_bit == netmask_max and node.bit == netmask_max:
            if node.has_prefix:
                if self._contain_netmask(node, netmask):
                    # perfect duplicate
                    if exclusive:
                        sc_errno.value = SC_EEXIST
                        return None
                else:
                    self._append_user_data(node, netmask, user)

                    # a /32 (or /128) is an exact host, not a netblock
                    if netmask == netmask_max:
                        return node

                    parent = node.parent
                    while parent is not None and netmask < (parent.bit + 1):
                        node = parent
                        parent = parent.parent

                    self._add_netmask_to_masks(node, netmask)
            return node

        # create the leaf node for the new key
        new_node = RadixNode(netmask_max, self.address_bytes)
        new_node.prefix_stream = bytearray(tmp_stream)
        new_node.has_prefix = True
        new_node.user_data = [RadixUserData(netmask, user)]

        # break the branch with an intermediate node at differ_bit
        inter_node = RadixNode(netmask_max, self.address_bytes)
        inter_node.has_prefix = False
        inter_node.bit = differ_bit
        inter_node.parent = node.parent

        self._process_internode(node, inter_node)

        if bittest(tmp_stream, differ_bit):
            inter_node.left = node
            inter_node.right = new_node
        else:
            inter_node.left = new_node
            inter_node.right = node
        new_node.parent = inter_node

        if node.parent is None:
            self.head = inter_node
        elif node.parent.right is node:
            node.parent.right = inter_node
        else:
            node.parent.left = inter_node

        node.parent = inter_node

        # insert the netmask into the tree
        if netmask != netmask_max:
            node = new_node
            parent = new_node.parent
            while parent is not None and netmask < (parent.bit + 1):
                node = parent
                parent = parent.parent
            self._add_netmask_to_masks(node, netmask)

        return new_node

    # -- FindKey / FindKeyIPNetblock ---------------------------------------

    def _find_key_ip_netblock(self, key_stream, node):
        """FindKeyIPNetblock(). Returns (node, user) or (None, None)."""
        netmask_max = self.netmask_max

        while node is not None and self._netmasks_empty(node):
            node = node.parent
        if node is None:
            return None, None

        tmp_stream = bytearray(key_stream)
        netmask_node = node

        for jj in range(0, netmask_max + 1):
            m = netmask_max - jj

            if not self._netmask_isset(netmask_node, m):
                continue

            for i in range(self.address_bytes):
                mask = 0xFFFFFFFF
                if ((i + 1) * 8) > m:
                    if ((i + 1) * 8 - m) < 8:
                        mask = (0xFFFFFFFF << ((i + 1) * 8 - m)) & 0xFFFFFFFF
                    else:
                        mask = 0
                tmp_stream[i] &= mask & 0xFF

            # NOTE: `node` is deliberately not reset to netmask_node between
            # iterations -- this mirrors the C control flow exactly.
            while node.bit < netmask_max:
                if bittest(tmp_stream, node.bit):
                    node = node.right
                else:
                    node = node.left
                if node is None:
                    return None, None

            if node.bit != netmask_max or not node.has_prefix:
                return None, None

            if bytes(node.prefix_stream) == bytes(tmp_stream):
                found, user = self._contain_netmask_and_get_user(node, m, False)
                if found:
                    return node, user

        return self._find_key_ip_netblock(tmp_stream, netmask_node.parent)

    def find_key(self, key_stream, netmask, exact_match):
        """FindKey(). Returns (node, user) or (None, None)."""
        netmask_max = self.netmask_max
        if self.head is None:
            return None, None

        node = self.head
        tmp_stream = bytearray(key_stream)

        while node.bit < netmask_max:
            if bittest(tmp_stream, node.bit):
                node = node.right
            else:
                node = node.left
            if node is None:
                return None, None

        if node.bit != netmask_max or not node.has_prefix:
            return None, None

        if bytes(node.prefix_stream) == bytes(tmp_stream):
            found, user = self._contain_netmask_and_get_user(
                node, netmask, True)
            if found:
                return node, user

        if exact_match:
            return None, None

        return self._find_key_ip_netblock(tmp_stream, node)

    def find_best_match(self, key_stream):
        """FindBestMatch(): longest-prefix / most-specific match."""
        return self.find_key(key_stream, self.netmask_max, False)


# ---------------------------------------------------------------------------
# String key insertion -- SCRadix4AddKeyIPV4String / SCRadix6AddKeyIPV6String
# ---------------------------------------------------------------------------


def _parse_u8_range_check(s, vmin, vmax):
    """StringParseU8RangeCheck() via ByteExtractString(strict=true).

    strtoull() semantics: optional leading whitespace and sign, then digits,
    and (strict) nothing after. Returns the value, or None on failure.
    """
    if s is None or len(s) > 23:
        return None
    i = 0
    n = len(s)
    while i < n and s[i] in " \t\n\v\f\r":
        i += 1
    neg = False
    if i < n and s[i] in "+-":
        neg = s[i] == "-"
        i += 1
    start = i
    while i < n and s[i].isdigit() and s[i].isascii():
        i += 1
    if i == start:
        return None  # endptr == ptr: no numeric value
    val = int(s[start:i])
    if neg:
        # strtoull() wraps; such a value can never land in [0, 32]/[0, 128].
        val = (-val) & 0xFFFFFFFFFFFFFFFF
    if i != n:
        return None  # strict: extra characters
    if val > 0xFF:
        return None
    if val < vmin or val > vmax:
        return None
    return val


def add_key_ipv4_string(tree, s, user):
    """SCRadix4AddKeyIPV4String(). Returns True, or False with sc_errno set."""
    netmask = 32

    # strlcpy(ip_str, str, sizeof(ip_str) - 2) with char ip_str[32]
    ip_str = s[:29]

    if "/" in ip_str:
        ip_str, mask_str = ip_str.split("/", 1)
        if "." in mask_str:
            # dotted netmask not supported
            sc_errno.value = SC_EINVAL
            return False
        cidr = _parse_u8_range_check(mask_str, 0, 32)
        if cidr is None:
            sc_errno.value = SC_EINVAL
            return False
        netmask = cidr

    try:
        packed = socket.inet_pton(socket.AF_INET, ip_str)
    except (OSError, UnicodeEncodeError):
        sc_errno.value = SC_EINVAL
        return False

    if tree.add_key(bytearray(packed), netmask, user, True) is None:
        return False
    return True


def add_key_ipv6_string(tree, s, user):
    """SCRadix6AddKeyIPV6String(). Returns True, or False with sc_errno set."""
    netmask = 128

    # strlcpy(ip_str, str, sizeof(ip_str)) with char ip_str[80]
    ip_str = s[:79]

    if "/" in ip_str:
        ip_str, mask_str = ip_str.split("/", 1)
        if "." in mask_str:
            sc_errno.value = SC_EINVAL
            return False
        cidr = _parse_u8_range_check(mask_str, 0, 128)
        if cidr is None:
            sc_errno.value = SC_EINVAL
            return False
        netmask = cidr

    try:
        packed = socket.inet_pton(socket.AF_INET6, ip_str)
    except (OSError, UnicodeEncodeError):
        sc_errno.value = SC_EINVAL
        return False

    addr = bytearray(packed)
    if netmask != 128:
        # host bits set -> the C warns and adds the masked address instead
        mask6 = cidr_get_ipv6(netmask)
        masked = bytearray(16)
        for i in range(16):
            masked[i] = addr[i] & mask6[i]
        if bytes(masked) != bytes(addr):
            addr = masked

    if tree.add_key(addr, netmask, user, True) is None:
        return False
    return True


# ---------------------------------------------------------------------------
# src/util-host-os-info.c
# ---------------------------------------------------------------------------


class DuplicateAddress(Exception):
    pass


class InvalidAddress(Exception):
    pass


class HostOSInfo(object):
    """sc_hinfo_tree4 / sc_hinfo_tree6 plus their accessors."""

    def __init__(self):
        self.tree4 = RadixTree(32, 4)
        self.tree6 = RadixTree(128, 16)

    def add_host_os_info(self, host_os, host_os_ip_range, is_ipv4):
        """SCHInfoAddHostOSInfo(). Returns the policy value, or -1."""
        if (host_os is None or host_os_ip_range is None
                or len(host_os_ip_range) == 0):
            return -1

        v = map_enum_name_to_value(host_os)
        if v == -1:
            return -1
        user_data = v

        if host_os_ip_range.lower() == "default":
            host_os_ip_range = "0.0.0.0/0" if is_ipv4 else "::/0"

        ip_str = host_os_ip_range
        ip_str_rem = None
        recursive = False
        if "," in ip_str:
            ip_str, ip_str_rem = ip_str.split(",", 1)
            recursive = True

        sc_errno.value = SC_OK
        if ":" not in ip_str:
            ok = add_key_ipv4_string(self.tree4, ip_str, user_data)
        else:
            ok = add_key_ipv6_string(self.tree6, ip_str, user_data)

        if not ok:
            if sc_errno.value == SC_EEXIST:
                raise DuplicateAddress(ip_str)
            raise InvalidAddress(ip_str)

        if recursive:
            # The C discards this return value.
            self.add_host_os_info(host_os, ip_str_rem, is_ipv4)

        return user_data

    def get_host_os_flavour(self, s):
        """SCHInfoGetHostOSFlavour(). Returns the policy value, or -1."""
        if s is None or "/" in s:
            return -1

        if ":" in s:
            try:
                packed = socket.inet_pton(socket.AF_INET6, s)
            except (OSError, UnicodeEncodeError):
                return -1
            _node, user = self.tree6.find_best_match(bytearray(packed))
        else:
            try:
                packed = socket.inet_pton(socket.AF_INET, s)
            except (OSError, UnicodeEncodeError):
                return -1
            _node, user = self.tree4.find_best_match(bytearray(packed))

        if user is None:
            return -1
        return user

    def get_host_os_flavour_name(self, s):
        v = self.get_host_os_flavour(s)
        if v == -1:
            return "none"
        return map_enum_value_to_name(v)


# ---------------------------------------------------------------------------
# Minimal YAML reader. PyYAML cannot parse suricata.yaml.in (autoconf @...@
# placeholders), and we only need nested maps of scalars/sequences, so we do it
# directly and avoid the dependency entirely.
# ---------------------------------------------------------------------------


def _strip_comment(line):
    out = []
    quote = None
    i = 0
    while i < len(line):
        ch = line[i]
        if quote is not None:
            out.append(ch)
            if ch == "\\" and quote == '"' and i + 1 < len(line):
                out.append(line[i + 1])
                i += 2
                continue
            if ch == quote:
                quote = None
        elif ch in "\"'":
            quote = ch
            out.append(ch)
        elif ch == "#":
            # a comment starts at '#' when at line start or after whitespace
            if not out or out[-1] in " \t":
                break
            out.append(ch)
        else:
            out.append(ch)
        i += 1
    return "".join(out).rstrip()


def _unquote(v):
    v = v.strip()
    if len(v) >= 2 and v[0] == v[-1] and v[0] in "\"'":
        return v[1:-1]
    return v


def _parse_flow_seq(v):
    """Parse a single-line flow sequence: [a, b, c]."""
    inner = v[1:-1].strip()
    if not inner:
        return []
    items = []
    cur = []
    quote = None
    for ch in inner:
        if quote is not None:
            cur.append(ch)
            if ch == quote:
                quote = None
        elif ch in "\"'":
            quote = ch
            cur.append(ch)
        elif ch == ",":
            items.append(_unquote("".join(cur)))
            cur = []
        else:
            cur.append(ch)
    items.append(_unquote("".join(cur)))
    return [x for x in items if x != ""]


def _scalar(v):
    v = v.strip()
    if v == "" or v in ("~", "null", "Null", "NULL"):
        return None
    if v.startswith("[") and v.endswith("]"):
        return _parse_flow_seq(v)
    return _unquote(v)


def _tokenize(text):
    """-> list of (indent, content) for significant lines."""
    lines = []
    for raw in text.splitlines():
        if raw.lstrip().startswith("%"):  # %YAML directive
            continue
        if raw.strip() in ("---", "..."):
            continue
        stripped = _strip_comment(raw)
        if not stripped.strip():
            continue
        indent = len(stripped) - len(stripped.lstrip(" "))
        lines.append((indent, stripped.strip()))
    return lines


def _split_key(content):
    """Split "key: value" honoring quotes. -> (key, value) or None."""
    quote = None
    i = 0
    while i < len(content):
        ch = content[i]
        if quote is not None:
            if ch == quote:
                quote = None
        elif ch in "\"'":
            quote = ch
        elif ch == ":":
            if i + 1 >= len(content) or content[i + 1] in " \t":
                return _unquote(content[:i]), content[i + 1:].strip()
        i += 1
    return None


def _parse_block(lines, pos, indent):
    """Parse a block at `indent`. -> (value, next_pos)."""
    if pos >= len(lines):
        return None, pos

    if lines[pos][1].startswith("- ") or lines[pos][1] == "-":
        return _parse_seq(lines, pos, indent)

    result = {}
    while pos < len(lines):
        cur_indent, content = lines[pos]
        if cur_indent < indent:
            break
        if cur_indent > indent:
            pos += 1  # unexpected deeper line; skip
            continue

        kv = _split_key(content)
        if kv is None:
            pos += 1
            continue
        key, rest = kv

        if rest:
            result[key] = _scalar(rest)
            pos += 1
            continue

        # value lives in the following block, which for a sequence may sit at
        # the same indentation as its key
        pos += 1
        if pos < len(lines):
            nxt_indent, nxt_content = lines[pos]
            is_seq = nxt_content.startswith("- ") or nxt_content == "-"
            if nxt_indent > cur_indent or (is_seq and nxt_indent == cur_indent):
                result[key], pos = _parse_block(lines, pos, nxt_indent)
                continue
        result[key] = None

    return result, pos


def _parse_seq(lines, pos, indent):
    items = []
    while pos < len(lines):
        cur_indent, content = lines[pos]
        if cur_indent != indent or not (content.startswith("- ")
                                        or content == "-"):
            break
        item = content[1:].strip()
        if item:
            nested = _split_key(item)
            if nested is not None:
                # "- key: value" -> a map item
                key, rest = nested
                m = {key: _scalar(rest)}
                pos += 1
                while pos < len(lines) and lines[pos][0] > indent:
                    sub, pos = _parse_block(lines, pos, lines[pos][0])
                    if isinstance(sub, dict):
                        m.update(sub)
                items.append(m)
                continue
            items.append(_scalar(item))
            pos += 1
        else:
            pos += 1
            if pos < len(lines) and lines[pos][0] > indent:
                sub, pos = _parse_block(lines, pos, lines[pos][0])
                items.append(sub)
            else:
                items.append(None)
    return items, pos


def yaml_load(path):
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        text = fh.read()
    lines = _tokenize(text)
    if not lines:
        return {}
    value, _pos = _parse_block(lines, 0, lines[0][0])
    return value


# ---------------------------------------------------------------------------
# SCHInfoLoadFromConfig()
# ---------------------------------------------------------------------------


def load_from_config(path):
    """Build a HostOSInfo from a policy document.

    Root keys are flavour names; a `host-os-policy` wrapper (as in
    suricata.yaml.in) is descended into when present.
    """
    doc = yaml_load(path)
    if not isinstance(doc, dict):
        return HostOSInfo()

    root = doc
    if "host-os-policy" in doc and isinstance(doc["host-os-policy"], dict):
        root = doc["host-os-policy"]

    info = HostOSInfo()
    for flavour, hosts in root.items():
        # Invalid flavour keys are ignored rather than loaded.
        if map_enum_name_to_value(flavour) == -1:
            continue
        if hosts is None:
            continue
        if isinstance(hosts, str):
            hosts = [hosts]
        elif not isinstance(hosts, list):
            continue

        for host in hosts:
            if host is None or not isinstance(host, str) or host == "":
                continue
            is_ipv4 = 0 if ":" in host else 1
            info.add_host_os_info(flavour, host, is_ipv4)

    return info


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

USAGE = (
    "usage: ospolicy cidr ipv4-mask <dotted-quad>\n"
    "       ospolicy cidr ipv4-prefix <n>\n"
    "       ospolicy cidr ipv6-prefix <n>\n"
    "       ospolicy load <yaml-path>   (IPs on stdin)\n"
)


def cmd_cidr(argv):
    if len(argv) != 2:
        sys.stderr.write(USAGE)
        return 2
    kind, arg = argv

    if kind == "ipv4-mask":
        try:
            packed = socket.inet_pton(socket.AF_INET, arg)
        except (OSError, UnicodeEncodeError):
            sys.stderr.write("invalid netmask\n")
            return 1
        # in_addr.s_addr is network byte order, which is what CIDRFromMask
        # ntohl()s back.
        sys.stdout.write("%d\n" % cidr_from_mask(
            int.from_bytes(packed, "big")))
        return 0

    if kind == "ipv4-prefix":
        try:
            n = int(arg, 10)
        except ValueError:
            sys.stderr.write("invalid prefix\n")
            return 1
        sys.stdout.write("%08x\n" % cidr_get(n))
        return 0

    if kind == "ipv6-prefix":
        try:
            n = int(arg, 10)
        except ValueError:
            sys.stderr.write("invalid prefix\n")
            return 1
        sys.stdout.write("%s\n" % cidr_get_ipv6(n).hex())
        return 0

    sys.stderr.write(USAGE)
    return 2


def cmd_load(argv):
    if len(argv) != 1:
        sys.stderr.write(USAGE)
        return 2
    path = argv[0]

    try:
        info = load_from_config(path)
    except DuplicateAddress:
        sys.stderr.write("duplicate\n")
        return 1
    except InvalidAddress as exc:
        sys.stderr.write("invalid address '%s'\n" % exc.args[0])
        return 1
    except OSError as exc:
        sys.stderr.write("cannot read '%s': %s\n" % (path, exc.strerror))
        return 1

    out = []
    for line in sys.stdin:
        ip = line.strip()
        if not ip:
            continue
        out.append("%s %s\n" % (ip, info.get_host_os_flavour_name(ip)))
    sys.stdout.write("".join(out))
    return 0


def main(argv):
    if len(argv) < 2:
        sys.stderr.write(USAGE)
        return 2
    cmd = argv[1]
    if cmd == "cidr":
        return cmd_cidr(argv[2:])
    if cmd == "load":
        return cmd_load(argv[2:])
    sys.stderr.write(USAGE)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv))

