#!/usr/bin/env python3
"""Differential test: /results/ospolicy python port vs the real-C oracle."""
import importlib.util
import random
import subprocess
import sys

spec = importlib.util.spec_from_loader(
    "ospolicy",
    importlib.machinery.SourceFileLoader("ospolicy", "/results/ospolicy"))
osp = importlib.util.module_from_spec(spec)
spec.loader.exec_module(osp)

FLAVOURS = ["windows", "linux", "bsd", "bsd-right", "old-linux", "old-solaris",
            "solaris", "hpux10", "hpux11", "irix", "macos", "vista",
            "windows2k3", "none"]


def run_case(adds, lookups):
    # ---- oracle ----
    cmds = []
    for flav, rng in adds:
        cmds.append("A %s %s" % (flav, rng))
    for ip in lookups:
        cmds.append("L %s" % ip)
    cmds.append("Q")
    proc = subprocess.run(["/tmp/oracle/oracle"], input="\n".join(cmds) + "\n",
                          capture_output=True, text=True)
    oracle_out = [l for l in proc.stdout.splitlines()
                  if not l.startswith("ok ") and not l.startswith("err ")]

    # ---- python port ----
    info = osp.HostOSInfo()
    for flav, rng in adds:
        is_ipv4 = 0 if ":" in rng else 1
        try:
            info.add_host_os_info(flav, rng, is_ipv4)
        except (osp.DuplicateAddress, osp.InvalidAddress):
            pass  # oracle also refuses and carries on
    py_out = [info.get_host_os_flavour_name(ip) for ip in lookups]

    return oracle_out, py_out


def rand_v4():
    return "%d.%d.%d.%d" % tuple(random.randrange(256) for _ in range(4))


def rand_v6():
    if random.random() < 0.4:
        return "2001:db8:%x::%x" % (random.randrange(65536),
                                    random.randrange(65536))
    return ":".join("%x" % random.randrange(65536) for _ in range(8))


def main():
    random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 12345)
    fails = 0
    cases = 0

    for trial in range(400):
        v6 = (trial % 3 == 0)
        adds = []
        n = random.randrange(1, 14)
        for _ in range(n):
            flav = random.choice(FLAVOURS)
            if v6:
                ip = rand_v6()
                if random.random() < 0.7:
                    ip += "/%d" % random.choice(
                        [0, 1, 7, 8, 16, 24, 32, 48, 56, 64, 96, 120, 127, 128])
            else:
                ip = rand_v4()
                if random.random() < 0.7:
                    ip += "/%d" % random.choice(
                        [0, 1, 4, 8, 12, 16, 20, 22, 24, 25, 28, 30, 31, 32])
            adds.append((flav, ip))

        lookups = []
        for _ in range(random.randrange(1, 12)):
            if v6:
                lookups.append(rand_v6())
            else:
                lookups.append(rand_v4())
        # also look up the added addresses themselves, and near-neighbours
        for _flav, rng in adds:
            base = rng.split("/")[0]
            lookups.append(base)
        if not v6:
            for _flav, rng in adds:
                base = rng.split("/")[0]
                parts = [int(x) for x in base.split(".")]
                parts[3] = (parts[3] + random.choice([1, 255, 128])) % 256
                lookups.append("%d.%d.%d.%d" % tuple(parts))
                parts2 = [int(x) for x in base.split(".")]
                parts2[2] = (parts2[2] + 1) % 256
                lookups.append("%d.%d.%d.%d" % tuple(parts2))

        o, p = run_case(adds, lookups)
        cases += len(lookups)
        if o != p:
            fails += 1
            print("MISMATCH trial %d" % trial)
            print("  adds:", adds)
            for i, (a, b) in enumerate(zip(o, p)):
                if a != b:
                    print("  lookup %s: oracle=%s python=%s"
                          % (lookups[i], a, b))
            if len(o) != len(p):
                print("  length differs", len(o), len(p))
            if fails > 5:
                print("too many failures, stopping")
                return 1

    print("trials=400 lookups=%d mismatched_trials=%d" % (cases, fails))
    return 1 if fails else 0


if __name__ == "__main__":
    sys.exit(main())

